questions.answer:
async function mapLimit(items, limit, fn) {
  const results = new Array(items.length);
  let next = 0;

  async function worker() {
    while (next < items.length) {
      const index = next++;
      results[index] = await fn(items[index], index);
    }
  }

  const workers = Array.from(
    { length: Math.min(limit, items.length) },
    () => worker()
  );
  await Promise.all(workers);
  return results;
}

const ids = [1, 2, 3, 4, 5];
mapLimit(ids, 2, async (id) => {
  await new Promise((r) => setTimeout(r, 20));
  return id * 10;
}).then((values) => console.log(values));
// [ 10, 20, 30, 40, 50 ]

A fixed pool of workers pulls indexes from a shared counter, so at most limit fn calls are active. Writing into results[index] keeps the output aligned with the input even though completion order varies. Promise.all waits for the workers to drain. The Math.min guard handles an empty list or a limit larger than the input. If fn rejects, Promise.all rejects and remaining workers stop pulling new items — catch inside fn if you want per-item failure handling.

